  vs: [['langgraph', 'LangGraph gives lower-level control of state and flow; CrewAI offers a higher-level role/task model.']],
  tech: ['CrewAI (Python)', 'tool integrations'],
  patterns: ['Sequential crew with clearly scoped tasks.', 'Hierarchical process with a manager agent.', 'Structured task outputs passed between agents.'],
  fails: ['Vague role descriptions causing overlap and wasted tokens.', 'Unbounded delegation.', 'Opaque runs hard to debug without tracing.', 'Assuming roles equal reliability.'],
  fix: [['Outputs inconsistent between tasks', 'Define expected output schemas and tighten task descriptions.'], ['High token usage', 'Reduce agents, cap iterations, use cheaper models for simple roles.']],
  guide: ['Decide if a fixed workflow would suffice.', 'Define tasks and expected outputs first.', 'Assign minimal tools per agent.', 'Trace and evaluate.'],
  when: 'Good for fast prototypes of role-structured pipelines.',
  sources: [['CrewAI documentation', 'docs.crewai.com (verify)'], ['CrewAI repository', 'github.com/crewAIInc/crewAI (verify)']],
  fresh: 'volatile', tsc: ['Current API, versions, commercial offerings and licence.'],
  keywords: ['roles', 'tasks', 'crew']
