  vs: [['ollama', 'Ollama adds model management and a friendlier CLI/API; llama.cpp is the lower-level engine with more knobs.'], ['vllm', 'vLLM targets GPU server throughput.']],
  tech: ['llama.cpp', 'GGUF', 'Metal / CUDA / Vulkan backends'],
  patterns: ['Choose quantisation by memory budget (test quality).', 'Offload as many layers to GPU as fits.', 'Bind the server to localhost unless secured.', 'Use grammars for structured output.'],
  fails: ['Model too large for RAM causing swapping.', 'Build flags missing GPU backend.', 'Exposing the server to the network without auth.', 'Outdated GGUF files for newer builds.'],
  fix: [['Very slow generation', 'Check that GPU offload is active; use a smaller quantisation or model.'], ['Model fails to load', 'Match GGUF version/format to the llama.cpp build.']],
  guide: ['Estimate memory needs.', 'Download a trusted GGUF.', 'Run with a small context first.', 'Tune GPU layers and threads.', 'Secure the server.'],
